:root {
    --layout-max-width: 1300px;
    --layout-news-columns: repeat(auto-fill, minmax(340px, 1fr));
    --layout-card-gap: 5rem 3rem;
    --layout-card-direction: column;
    --layout-animation-style: perspective-assemble;
    --card-perspective: 1200px;
}

#news-container {
    max-width: var(--layout-max-width);
    margin: 8rem auto;
    padding: 2rem;
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    perspective: var(--card-perspective);
    transform-style: preserve-3d;
}

.news-card {
    position: relative;
    background: var(--morpho-bg-primary);
    border: 1px solid rgba(var(--morpho-accent-primary-rgb), 0.2);
