    flex-direction: var(--layout-card-direction);
    gap: 1.5rem;
    transition: 
        transform 0.5s cubic-bezier(0.23, 1, 0.32, 1), 
        box-shadow 0.5s ease, 
        border-color 0.5s ease;

    /* Scroll-driven animation setup */
    view-timeline-name: --card-scroll-reveal;
    view-timeline-axis: block;
    animation-name: var(--layout-animation-style);
    animation-fill-mode: both;
    animation-timeline: --card-scroll-reveal;
    animation-range: entry 5% cover 35%;
}

.news-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    background: var(--morpho-accent-gradient);
    opacity: 0.6;
}

